insert into public.events(id,host_id,room_code,name,event_date,status,display_mode)values('a8000000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000001','TIME20','Timeout Night','2026-08-20','lobby','game');
insert into public.teams(id,event_id,auth_user_id,name,mascot_id)values('d8000000-0000-0000-0000-000000000001','a8000000-0000-0000-0000-000000000001','28000000-0000-0000-0000-000000000001','Late Team','owl'),('d8000000-0000-0000-0000-000000000002','a8000000-0000-0000-0000-000000000001','28000000-0000-0000-0000-000000000002','Other Team','bee');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"18000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select public.save_perfect_lie_round('a8000000-0000-0000-0000-000000000001','Perfect Lie','[{"title":"General Knowledge","questions":[{"question_text":"What is true?","correct_answer":"Truth"}]}]');reset role;
select set_config('test.timeout_q',(select id::text from public.perfect_lie_questions where event_id='a8000000-0000-0000-0000-000000000001'),true);
set local role authenticated;select set_config('request.jwt.claims','{"sub":"18000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select public.advance_perfect_lie_question('a8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid);select public.start_perfect_lie_question('a8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,20);
select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select throws_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,'Too early')$$,'55000','Submit your answer attempt first.','lie RPC cannot bypass active answer deadline');reset role;
update public.perfect_lie_round_states set knowledge_deadline_at=clock_timestamp()-interval'1 second';update public.events set question_started_at=clock_timestamp()-interval'2 seconds',question_deadline_at=clock_timestamp()-interval'1 second';
set local role authenticated;select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000002","role":"authenticated","is_anonymous":true}',true);select throws_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,'Ownership attack')$$,'42501','Team ownership required','another Team cannot create timeout state');
select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select lives_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,'A convincing late lie')$$,'expired Team atomically enters lie writing and submits');select lives_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,' a convincing late lie ')$$,'identical timeout lie retry is idempotent');reset role;
select ok((select timed_out and not knew_truth and initial_answer is null from public.perfect_lie_responses where team_id='d8000000-0000-0000-0000-000000000001'),'timeout response cannot secure truth points or invent an answer');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select ok((public.get_team_room_state('TIME20')->'perfect_lie'->'my_response'->>'timed_out')::boolean,'refresh restores timeout-specific Team state');select is(public.get_team_room_state('TIME20')->'perfect_lie'->'my_lie'->>'text','A convincing late lie','refresh restores submitted lie waiting state');
select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000002","role":"authenticated","is_anonymous":true}',true);select lives_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000002',current_setting('test.timeout_q')::uuid,'Atomic timeout lie')$$,'second Team uses the same canonical timeout route');select lives_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000002',current_setting('test.timeout_q')::uuid,'  atomic   timeout lie ')$$,'second Team retry is idempotent');reset role;select ok((select timed_out and not knew_truth from public.perfect_lie_responses where team_id='d8000000-0000-0000-0000-000000000002'),'atomic timeout Team cannot earn initial truth credit');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"18000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select lives_ok($$select public.close_perfect_lie_writing('a8000000-0000-0000-0000-000000000001')$$,'Host closes writing');select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select throws_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,'Different late lie')$$,'55000','Lie submissions have closed.','lie is rejected only after Host closes writing');select * from finish();rollback;
